INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Ingin Menyapa dalam Bahasa Portugis tapi Takut Salah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Bahasa Portugis dipakai lebih dari 260 juta orang di Brasil, Portugal, dan beberapa negara Afrika. Banyak pemula Indonesia tertarik karena musik bossa nova, sepak bola, dan peluang kerja, tetapi urung belajar karena takut salah pengucapan bunyi sengau atau memakai sapaan yang tidak sopan. Kabar baiknya: sapaan dasar bahasa Portugis mudah dipelajari dan orang penutur asli sangat menghargai usaha orang asing yang mencoba.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Karakter Bahasa Portugis yang Perlu Diketahui$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Bahasa Portugis adalah bahasa Roman, saudara dekat bahasa Spanyol. Ciri khasnya adalah bunyi sengau (ditandai ã, õ) seperti pada kata pão (roti) dan bom (baik). Di Brasil sapaan cenderung santai, sedangkan di Portugal lebih formal. Untuk pemula, fokuslah pada varian Brasil karena lebih sering dipakai dalam konten hiburan dan lebih mudah ditemukan materi belajarnya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat dan Persiapan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Aplikasi kamus Portugis-Indonesia atau Portugis-Inggris untuk cek pengucapan$$, $$Aplikasi flashcard untuk menghafal 20 sapaan inti$$, $$Akses video/audio penutur asli Brasil untuk meniru intonasi$$, $$Buku catatan kecil untuk mencatat frasa yang sering dipakai$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Kuasai 10 Sapaan Inti$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$1. Bom dia (bong DZEE-ah) = selamat pagi, dipakai sampai sekitar tengah hari$$, $$2. Boa tarde (BOH-ah TAHR-djee) = selamat siang/sore$$, $$3. Boa noite (BOH-ah NOY-tchee) = selamat malam, juga dipakai saat berpisah di malam hari$$, $$4. Olá (oh-LAH) = halo, sapaan netral paling aman$$, $$5. Oi (oy) = hai, sapaan santai antar teman$$, $$6. Como vai? (KOH-moo VY) = apa kabar? Jawab: Vou bem, obrigado/a$$, $$7. Prazer (prah-ZEHR) = senang bertemu denganmu, dipakai saat berkenalan$$, $$8. Obrigado (pria) / Obrigada (wanita) = terima kasih, sesuaikan dengan jenis kelamin pembicara$$, $$9. Por favor (poor fah-VOHR) = tolong$$, $$10. Tchau (tchow) = dadah, untuk perpisahan santai$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Kesalahan Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Kesalahan paling umum: mengucapkan obrigado/obrigada terbalik (ingat, yang berubah adalah pembicara, bukan lawan bicara). Kesalahan kedua: memakai tu (kamu, informal) ke orang yang lebih tua atau belum akrab — gunakan senhor/senhora (Bapak/Ibu) bila ragu. Kesalahan ketiga: mengabaikan bunyi sengau ã/õ sehingga bom (baik) terdengar seperti bobo. Latih bunyi sengau dengan menahan sebagian udara lewat hidung.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Uji dirimu: tanpa melihat catatan, ucapkan sapaan yang tepat untuk situasi berikut — bertemu teman jam 9 pagi, berpisah dengan sopir taksi jam 8 malam, berkenalan dengan rekan kerja baru, dan berterima kasih kepada pelayan restoran. Jika bisa menjawab keempatnya dengan pengucapan yang jelas, fondasi sapaanmu sudah kuat.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Bau Mulut Mengganggu Percaya Diri$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Bau mulut (halitosis) membuat tidak nyaman saat berbicara dekat dengan orang lain dan menurunkan rasa percaya diri. Banyak orang tidak sadar dirinya bau mulut karena hidung beradaptasi terhadap bau sendiri. Artikel ini membahas informasi umum tentang penyebab dan cara mengatasinya. Ini bukan pengganti nasihat medis — konsultasikan ke dokter atau dokter gigi bila keluhan menetap.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Dari Mana Bau Mulut Berasal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Sebagian besar bau mulut berasal dari dalam mulut sendiri: sisa makanan yang membusuk di sela gigi, plak, gigi berlubang, radang gusi, dan lapisan putih di lidah tempat bakteri berkembang. Penyebab lain meliputi mulut kering (misalnya saat bangun tidur atau kurang minum), merokok, makanan berbau tajam seperti bawang dan jengkol, serta kondisi medis tertentu seperti infeksi saluran napas, gangguan lambung, atau diabetes yang tidak terkontrol.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat dan Persiapan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Sikat gigi berbulu lembut dan pasta gigi berfluoride$$, $$Benang gigi (dental floss) atau sikat sela$$, $$Pembersih lidah atau sikat gigi untuk membersihkan permukaan lidah$$, $$Obat kumur antiseptik bila disarankan dokter gigi$$, $$Botol minum untuk menjaga asupan air putih$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Rutinitas Kebersihan Mulut yang Benar$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$1. Sikat gigi dua kali sehari, pagi setelah sarapan dan malam sebelum tidur, selama dua menit$$, $$2. Bersihkan permukaan lidah dari pangkal ke ujung setiap kali menyikat gigi$$, $$3. Gunakan benang gigi sekali sehari untuk membersihkan sela gigi yang tak terjangkau sikat$$, $$4. Minum air putih yang cukup agar mulut tidak kering, terutama setelah bangun tidur$$, $$5. Kurangi rokok dan makanan berbau tajam bila bau mulut sering muncul$$, $$6. Periksa ke dokter gigi setiap enam bulan untuk membersihkan karang gigi dan memeriksa gigi berlubang$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko dan Hal yang Perlu Diwaspadai$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Jangan menutupi bau mulut hanya dengan permen atau penyegar napas tanpa mengatasi penyebabnya — itu seperti menyemprot parfum pada luka. Waspadai tanda bahaya: bau mulut yang tidak hilang setelah kebersihan mulut diperbaiki, disertai gusi berdarah, gigi goyang, nyeri menelan, atau bau seperti buah (bisa berkaitan dengan gula darah). Segera konsultasi ke dokter gigi atau dokter umum bila mengalami hal tersebut.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil dan Tindak Lanjut$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Evaluasi setelah dua minggu rutinitas baru: minta pendapat jujur orang terdekat, atau jilat punggung tangan, biarkan kering sebentar, lalu cium. Jika bau berkurang, pertahankan kebiasaan baiknya. Jika tidak ada perubahan, jangan tunda — jadwalkan pemeriksaan ke dokter gigi untuk mencari penyebab yang lebih dalam.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Danau Toba: Raksasa Vulkanik Sumatera Utara$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Danau Toba di Sumatera Utara adalah danau vulkanik terbesar di Indonesia dan Asia Tenggara, dengan luas sekitar 1.130 kilometer persegi. Danau ini terbentuk dari letusan supervulkan sekitar 74.000 tahun lalu, salah satu letusan terbesar dalam sejarah Bumi. Di tengahnya ada Pulau Samosir, pulau di dalam danau yang hampir sebesar Singapura, yang menjadi pusat budaya Batak Toba.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Danau Poso: Permata Sulawesi Tengah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Danau Poso adalah danau terdalam ketiga di Indonesia dengan kedalaman mencapai sekitar 450 meter. Airnya jernih kebiruan dan dikelilingi perbukitan hijau. Danau ini memiliki banyak spesies ikan endemik, artinya hanya hidup di danau ini dan tidak ditemukan di tempat lain di dunia, sehingga menjadi laboratorium alam yang penting bagi ilmuwan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Danau Singkarak: Sumber Ikan Bilih$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Danau Singkarak di Sumatera Barat terkenal sebagai habitat ikan bilih, ikan kecil endemik yang menjadi kuliner khas daerah sekitarnya. Danau tektonik ini memanjang sekitar 20 kilometer dan menjadi sumber air bagi pembangkit listrik tenaga air. Kehidupan masyarakat di sekitarnya sangat bergantung pada danau, dari perikanan hingga pariwisata.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Danau Sentani: Danau di Kaki Pegunungan Papua$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Danau Sentani di Papua dikelilingi perbukitan dan dihiasi pulau-pulau kecil. Danau ini terkenal dengan Festival Danau Sentani yang menampilkan budaya masyarakat setempat, termasuk tarian di atas perahu. Ekosistemnya unik dengan ikan pelangi Sentani yang berwarna-warni dan hanya hidup di perairan ini.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Danau Matano dan Towuti: Danau Purba Sulawesi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Danau Matano dan Danau Towuti di Sulawesi Selatan termasuk danau purba yang terbentuk jutaan tahun lalu. Danau Matano adalah danau terdalam di Indonesia dengan kedalaman lebih dari 590 meter. Karena terisolasi sangat lama, danau-danau ini memiliki keanekaragaman hayati luar biasa dengan banyak spesies udang, keong, dan ikan yang tidak ada di tempat lain.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Kecerdasan Buatan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Kecerdasan buatan (artificial intelligence/AI) adalah teknologi yang membuat komputer mampu melakukan tugas yang biasanya membutuhkan kecerdasan manusia, seperti mengenali gambar, memahami bahasa, dan mengambil keputusan. AI modern bekerja dengan belajar dari data dalam jumlah besar — semakin banyak contoh yang dilihat, semakin baik kemampuannya mengenali pola.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Cara Kerja: Belajar dari Data$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Sebagian besar AI saat ini memakai pembelajaran mesin (machine learning). Contoh sederhananya: untuk mengenali kucing, sistem diberi jutaan foto kucing hingga ia menemukan sendiri ciri-cirinya — telinga runcing, kumis, ekor. Model bahasa seperti chatbot dilatih dengan teks dalam jumlah raksasa sehingga mampu memprediksi kata berikutnya dan menghasilkan kalimat yang masuk akal.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$AI dalam Kehidupan Sehari-hari$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Tanpa disadari, AI sudah dipakai setiap hari: rekomendasi video dan musik, filter spam email, pengenalan wajah untuk membuka kunci HP, asisten suara, terjemahan otomatis, hingga fitur potret pada kamera yang memburamkan latar. Di bidang kesehatan, AI membantu membaca hasil rontgen; di pertanian, AI memprediksi cuaca dan hama.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Peluang: Membantu Manusia Bekerja Lebih Baik$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$AI unggul pada tugas berulang dan analisis data besar — misalnya meringkas dokumen panjang, memeriksa ribuan transaksi untuk menemukan penipuan, atau menerjemahkan bahasa secara instan. Dengan AI menangani pekerjaan rutin, manusia bisa fokus pada hal yang membutuhkan kreativitas, empati, dan penilaian moral. Negara yang menguasai AI berpotensi memimpin ekonomi digital.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Tantangan: Halusinasi, Bias, dan Etika$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$AI bukan tanpa masalah. Ia bisa berhalusinasi — menjawab dengan percaya diri padahal salah. Ia bisa mewarisi bias dari data latihannya. Ada pula kekhawatiran soal lapangan kerja, privasi data, dan penyalahgunaan seperti foto atau video palsu (deepfake). Karena itu, aturan dan literasi digital menjadi penting: selalu verifikasi informasi penting dari sumber tepercaya, jangan telan mentah-mentah jawaban AI.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, kamu diharapkan mampu: (1) menjelaskan pengertian notice dan fungsinya, (2) mengidentifikasi jenis-jenis notice, (3) memahami makna notice dalam berbagai konteks, dan (4) menulis notice sederhana dalam bahasa Inggris.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Notice$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Notice adalah pemberitahuan atau peringatan singkat yang ditulis untuk memberi informasi, perintah, atau larangan kepada orang banyak. Notice biasanya dipasang di tempat umum seperti sekolah, rumah sakit, taman, dan jalan raya. Ciri-cirinya: singkat, jelas, memakai kalimat perintah (imperative), dan sering disertai simbol atau gambar.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Jenis-jenis Notice$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', to_jsonb(ARRAY[$$Command (perintah): Keep Silent, Queue Here, Park Your Bike Here$$, $$Prohibition (larangan): No Smoking, No Parking, Do Not Enter, No Littering$$, $$Warning (peringatan): Beware of Dog, Danger: High Voltage, Wet Floor$$, $$Information (informasi): Lost and Found, Office Hours 8 AM - 4 PM, Library Open$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Ciri Kebahasaan dan Contoh$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Notice umumnya memakai kalimat imperatif seperti 'Keep off the grass' atau 'Do not feed the animals'. Untuk larangan, pola yang sering dipakai adalah 'No + V-ing' (No Smoking, No Swimming) atau 'Do not + verb'. Contoh di perpustakaan: 'Please return the books on time.' Di kolam renang: 'No running around the pool.' Cobalah amati notice di sekitarmu dan artikan maknanya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Latihan Soal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$$1. Apa perbedaan notice jenis command dan prohibition? Beri masing-masing satu contoh.$$, $$2. Terjemahkan ke bahasa Inggris: 'Dilarang membuang sampah sembarangan.'$$, $$3. Buatlah satu notice larangan yang cocok dipasang di kantin sekolah.$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$1. Command berisi perintah melakukan sesuatu (mis. Keep Silent), sedangkan prohibition berisi larangan (mis. No Smoking).$$, $$2. No littering. / Do not litter.$$, $$3. Contoh jawaban yang benar: No littering. / Keep the canteen clean. / Do not leave your trash on the table.$$])));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah belajar materi ini, kamu diharapkan bisa: (1) menjelaskan apa itu lingkungan, (2) menyebutkan jenis-jenis lingkungan di sekitarmu, (3) memberi contoh benda hidup dan benda tak hidup, dan (4) menunjukkan cara menjaga kebersihan lingkungan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Apa Itu Lingkungan?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Lingkungan adalah segala sesuatu yang ada di sekitar kita. Ada lingkungan rumah, lingkungan sekolah, dan lingkungan tempat bermain. Di dalam lingkungan ada benda hidup seperti manusia, hewan, dan tumbuhan, serta benda tak hidup seperti meja, batu, air, dan udara. Semua saling membutuhkan satu sama lain.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Lingkungan Rumah dan Sekolah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Lingkungan rumah terdiri dari rumah tempat tinggal, halaman, kebun, dan hewan peliharaan. Ayah, ibu, kakak, dan adik adalah bagian dari lingkungan rumah. Lingkungan sekolah terdiri dari ruang kelas, halaman, perpustakaan, kantin, dan lapangan, beserta guru dan teman-teman. Rumah dan sekolah yang bersih membuat penghuninya sehat dan belajar jadi menyenangkan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Menjaga Kebersihan Lingkungan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', to_jsonb(ARRAY[$$Membuang sampah pada tempatnya, pisahkan sampah basah dan kering bila bisa$$, $$Menyapu halaman rumah dan kelas sesuai jadwal piket$$, $$Tidak mencoret-coret dinding dan meja$$, $$Menyiram tanaman agar tetap hidup dan udara segar$$, $$Menghemat air dan mematikan keran setelah dipakai$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Latihan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', to_jsonb(ARRAY[$$1. Sebutkan tiga contoh benda hidup di lingkungan sekolahmu!$$, $$2. Sebutkan tiga contoh benda tak hidup di lingkungan rumahmu!$$, $$3. Apa yang kamu lakukan jika melihat teman membuang sampah sembarangan?$$])));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', to_jsonb(ARRAY[$$1. Contoh: guru, teman, pohon, bunga, kucing (jawaban bisa berbeda, asal benda hidup).$$, $$2. Contoh: meja, kursi, batu, air, televisi (jawaban bisa berbeda, asal benda tak hidup).$$, $$3. Menegur dengan sopan dan mengajak membuang sampah pada tempatnya.$$])));
